"use strict";App.Http.BookingSettings=function(){return{save:function(bookingSettings){var url=App.Utils.Url.siteUrl("booking_settings/save"),data={csrf_token:vars("csrf_token"),booking_settings:bookingSettings};return $.post(url,data)},generateKioskPairingCode:function(providerId,deviceName){return $.post(App.Utils.Url.siteUrl("booking_settings/generate_kiosk_pairing_code"),{csrf_token:vars("csrf_token"),provider_id:providerId,device_name:deviceName})},revokeKioskDevice:function(deviceId){return $.post(App.Utils.Url.siteUrl("booking_settings/revoke_kiosk_device"),{csrf_token:vars("csrf_token"),device_id:deviceId})}}}();